import{_ as e,C as o,o as s,c as n,H as t,Q as c}from"./chunks/framework.be8d362c.js";const y=JSON.parse('{"title":"迁移 Grafana 默认的 SQLite DB 变更使用 MySQL","description":"日常监控需求中希望将原来部署的 `Grafana` 默认使用的 `SQLite` 数据库迁移变更为 `MySQL`，方便后续部署多实例时可使用同一份数据源，有利于如需扩展。","frontmatter":{"date":"2024-07-04T00:00:00.000Z","title":"迁移 Grafana 默认的 SQLite DB 变更使用 MySQL","tags":["Grafana","SQLite","Monitor"],"description":"日常监控需求中希望将原来部署的 `Grafana` 默认使用的 `SQLite` 数据库迁移变更为 `MySQL`，方便后续部署多实例时可使用同一份数据源，有利于如需扩展。"},"headers":[],"relativePath":"posts/change-grafana-db-to-mysql.md","filePath":"posts/change-grafana-db-to-mysql.md"}'),d={name:"posts/change-grafana-db-to-mysql.md"},l=c('<h1 id="迁移-grafana-默认的-sqlite-db-数据改为使用-mysql-方式" tabindex="-1">迁移 Grafana 默认的 SQLite DB 数据改为使用 MySQL 方式 <a class="header-anchor" href="#迁移-grafana-默认的-sqlite-db-数据改为使用-mysql-方式" aria-label="Permalink to &quot;迁移 Grafana 默认的 SQLite DB 数据改为使用 MySQL 方式&quot;">​</a></h1><h2 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to &quot;背景&quot;">​</a></h2><p>Grafana 默认部署使用的是 <code>sqlite3</code> 文件存储数据，在于告警查询时可能遇到锁情况，加上考虑如有需要扩展多实例部署方式的话，默认的存储方式可能不太适合，所以计划将默认 DB 变更调节为 <code>MySQL</code> 并希望将现有数据迁移（因为不希望重新配置用户及告警规则等信息）。</p><h2 id="迁移过程的参考步骤" tabindex="-1">迁移过程的参考步骤 <a class="header-anchor" href="#迁移过程的参考步骤" aria-label="Permalink to &quot;迁移过程的参考步骤&quot;">​</a></h2><ul><li>首先需要暂停 <code>Grafana</code> 服务，导出默认的 <code>SQLite</code> 数据库文件，如 <code>grafana.db</code> ；</li><li>可借助 <code>Grafana</code> 官方提供的工具 <a href="https://github.com/grafana/database-migrator" target="_blank" rel="noreferrer"><code>database-migrator</code></a> 将数据库导出转化为支持 <code>MySQL</code> 协议的 <code>SQL</code> 文件；</li><li>修改 <code>Grafana</code> 配置文件 <code>grafana.ini</code> 数据库相关配置参数 <code>-e &quot;GF_DATABASE_URL=mysql://$db_username:$db_passwd@$db_host:$db_port/$db_name&quot;</code> 使用 <code>MySQL</code> 数据库；</li><li>重新启动 <code>Grafana</code> 让其在 <code>MySQL</code> 中设置数据库和表结构，初始化完再先关停下 <code>Grafana</code> ；</li><li>导入前面使用工具从 <code>SQLLite</code> 原生默认数据库中导出的 <code>sql</code> 数据到 <code>MySQL</code> 对应的 <code>DB</code> 中；</li><li>重新开启 <code>Grafana</code> 按理即可；</li></ul><h2 id="如果-sqlite-开启-wal-模式情况" tabindex="-1">如果 <code>SQLite</code> 开启 <code>WAL</code> 模式情况 <a class="header-anchor" href="#如果-sqlite-开启-wal-模式情况" aria-label="Permalink to &quot;如果 `SQLite` 开启 `WAL` 模式情况&quot;">​</a></h2><p>当 <code>SQLite</code> 开启 <code>wal</code> 模式的话，这种情况下，因为其数据是会分布在数据文件 <code>grafana.db</code> 和 日志文件 <code>grafana.db-wal</code> 中的<br> 同时，即便是简单重启 <code>Grafana</code> 服务也不一定会触发日志文件数据持久化合并到数据文件中，所以迁移过程中需要手动触发将这里的 日志文件 持久化合并到 数据文件中；</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-dark vp-code-dark"><code><span class="line"><span style="color:#6A737D;"># 暂停 grafana 服务后，拷贝备份出 grafana.db 和 grafana.db-wal 文件后，手动执行下面命令触发</span></span>\n<span class="line"><span style="color:#B392F0;">sqlite3</span><span style="color:#E1E4E8;"> </span><span style="color:#9ECBFF;">grafana.db</span><span style="color:#E1E4E8;"> </span><span style="color:#9ECBFF;">&quot;PRAGMA wal_checkpoint(TRUNCATE); VACUUM;&quot;</span></span></code></pre><pre class="shiki github-light vp-code-light"><code><span class="line"><span style="color:#6A737D;"># 暂停 grafana 服务后，拷贝备份出 grafana.db 和 grafana.db-wal 文件后，手动执行下面命令触发</span></span>\n<span class="line"><span style="color:#6F42C1;">sqlite3</span><span style="color:#24292E;"> </span><span style="color:#032F62;">grafana.db</span><span style="color:#24292E;"> </span><span style="color:#032F62;">&quot;PRAGMA wal_checkpoint(TRUNCATE); VACUUM;&quot;</span></span></code></pre></div><p>最后再按上面工具导出为 <code>sql</code> 文件；</p>',9);function r(i,p,f,h,b,_){const a=o("Comment");return s(),n("div",null,[l,t(a)])}const m=e(d,[["render",r]]);export{y as __pageData,m as default};
